        if height > 0 and height >= a[i]:
            # Completely cover a[i] with range
            return min(dp(i + 1, 0), 1 + dp(i + 1 - height // a[i], 0))

        # General case: 
        # - Use height range ops if available
        # - Otherwise create new ones or use individual

        ans = a[i] + dp(i + 1, 0)  # All individual

        if height > 0:
            # Use height to help
            ans = min(ans, 1 + dp(i + 1, 0))

        # Start a new range operation
        ans = min(ans, 1 + dp(i + 1, a[i]))

        return ans

