```python
def geometric_check(arr):
    """Check if array represents a valid geometric progression."""
    if len(arr) <= 1:
        return True

    all_zeros = all(x == 0 for x in arr)
    if all_zeros:
        return True

    ratio = None

    for i in range(len(arr) - 1):
        a = float(arr[i])
        b = float(arr[i + 1])

        if a == 0:
            if b == 0:
                continue  # 0 -> 0, ok, ratio not yet defined
            else:
                # 0 -> non-zero, invalid GP
                return False
        else:
            if ratio is None:
                ratio = b / a
            else:
                if abs(a * ratio - b) > 1e-9:
                    # Not consistent with the established ratio
                    return False

    return True


class Solution:
    def solve(self, input_str):
        lines = input_str.strip().split('\n')
        n = int(lines[0])
        parts = lines[1].split()
        nums = [int(x) for x in parts]

        # Check if already a GP
        if geometric_check(nums):
            return '0\n'

        # Try removing each element one at a time
        for i in range(n):
            sub = nums[:i] + nums[i+1:]
            if geometric_check(sub):
                return '1\n'

        return '2\n'

    def __call__(self, input_str):
        return self.solve(input_str)


def solution(input_str):
    sol = Solution()
    return sol(input_str)
