    assigned_count = 0

    while assigned_count < 20000:  # Generate enough mappings
        year_str = str(year)
        assigned = None

        # Check suffixes from shortest to longest
        for length in range(1, len(year_str) + 1):
            suffix = year_str[-length:]
            if suffix not in mapping:
                assigned = suffix
                break

        if assigned:
            mapping[assigned] = year
            assigned_count += 1

        # Safety limit
        if year > 10000000:
            break

        year += 1

    # Process each abbreviation and find its year
    results = []
    for abbr in abbreviations:
        # Extract the suffix after "IAO'"
        if "'" in abbr:
            suffix = abbr.split("'")[1]
            result = mapping.get(suffix, -1)
        else:
            result = -1
        results.append(str(result))

    return '\n'.join(results)
