def solution(input_string):
    def rev(n):
        return int(str(n)[::-1])

    def count_lucky(x, y):
        """Count lucky tickets (a, b) where 1 <= a <= x, 1 <= b <= y and a*b = rev(a)*rev(b)"""
        count = 0
        for a in range(1, x + 1):
            for b in range(1, y + 1):
                if a * b == rev(a) * rev(b):
                    count += 1
        return count

    # Parse input
    parts = input_string.strip().split()
    maxx = int(parts[0])
    maxy = int(parts[1])
    w = int(parts[2])

    # Check if any valid solution exists
    max_x = maxx
    max_y = maxy

    # Try all possible combinations with minimal x*y
    # Start from smallest product and check
    best_x, best_y = -1, -1
    found = False

    # For efficiency, limit the search space
    # We want minimal x*y, so iterate by product size
    min_product = maxx * 1 if maxx < maxy else maxy * 1

    # Direct enumeration for small constraints
    for x in range(1, min(maxx, maxy) + 1):
        for y in range(1, maxy + 1):
            if x * y > maxx * maxy:  # Upper bound
                break
            if x > maxx or y > maxy:
                continue

            lucky_count = 0

            # Count lucky tickets
            for a in range(1, x + 1):
                for b in range(1, y + 1):
                    if a * b == rev(a) * rev(b):
                        lucky_count += 1

            if lucky_count >= w and x <= maxx and y <= maxy:
                if best_x == -1 or x * y < best_x * best_y:
                    best_x, best_y = x, y
                    found = True
                    # If we find a solution with smallest product, we could potentially break
                    # But there might be multiple with same product

    if found and best_x != -1 and best_y != -1:
        return f"{best_x} {best_y}\n"
    else:
