    # Limit search based on constraints
    # Try starting from small x, y combinations and find ones with enough lucky tickets
    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            # Pruning: if current x*y is already worse than best, skip
            if best is not None and x * y >= best[0] * best[1]:
                break  # y won't decrease, so continue to next x

            # Count lucky tickets
            lucky = 0
            for a in range(1, x + 1):
