    # LCA query and max edge on path
    def query_max(u, v):
        if u == v:
            return 0

        if depth[u] < depth[v]:
            u, v = v, u

        # Bring u to same depth as v
        diff = depth[u] - depth[v]
        for j in range(LOG):
            if (diff >> j) & 1:
                u = up[u][j]

        if u == v:
            return max_edge[depth[u]][0] if u != 0 else 0

        # Find LCA
        for j in range(LOG - 1, -1, -1):
            if up[u][j] != up[v][j]:
                u = up[u][j]
                v = up[v][j]

        lca = up[u][0]

        # Max on path u->lca
        ans = 0
        curr = u
        for j in range(LOG - 1, -1, -1):
            if depth[curr] - (1 << j) >= depth[lca]:
                ans = max(ans, max_edge[curr][j])
                curr = up[curr][j]

        # Max on path v->lca
        curr = v
        for j in range(LOG - 1, -1, -1):
            if depth[curr] - (1 << j) >= depth[lca]:
                ans = max(ans, max_edge[curr][j])
                curr = up[curr][j]

        return ans

    # Answer queries
    output = []
    for u, v, w, orig_idx in edges:
        if not is_in_mst(u, v):
            mx_on_path = query_max(u, v)
            output.append(str(mx_on_path))

    return '\n'.join(output)
