    current_x, current_y = x0, y0

    if grid[current_x][current_y] == 1:
        action_list.append('2')
        grid[current_x][current_y] = 0

    remaining = set((i, j) for i in range(n) for j in range(n) if grid[i][j] == 1)

    def dfs():
        nonlocal current_x, current_y, action_list, max_actions

        if len(action_list) > max_actions:
            return False

        if not remaining:
            return current_x == x0 and current_y == y0

        if grid[current_x][current_y] == 1 and (current_x, current_y) in remaining:
            action_list.append('2')
            grid[current_x][current_y] = 0
