import sys
import collections

def solution(input_str):
    data = input_str.strip().split()
    if not data:
        return ""

    n = int(data[0])
    m = int(data[1])

    adj = [[] for _ in range(n + 1)]
    idx = 2
    for _ in range(m):
        u = int(data[idx])
        v = int(data[idx + 1])
        idx += 2
        adj[u].append(v)

    # Compute all-pairs shortest paths using BFS from each node
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        dist[start][start] = 0
        queue = [start]
        head = 0
        while head < len(queue):
            u = queue[head]
            head += 1
            for v in adj[u]:
                if dist[start][v] == float('inf'):
                    dist[start][v] = dist[start][u] + 1
                    queue.append(v)

    # Precompute best_to[b]: up to 2 values of (dist[a][b], a) where a != b
    best_to = [None] * (n + 1)
    for b in range(1, n + 1):
        candidates = []
        for a in range(1, n + 1):
            if a != b and dist[a][b] != float('inf'):
                candidates.append((dist[a][b], a))
        if not candidates:
            best_to[b] = []
        else:
            candidates.sort(reverse=True)
            best_to[b] = candidates[:2]

    # Precompute best_from[c]: up to 2 values of (dist[c][d], d) where d != c
    best_from = [None] * (n + 1)
    for c in range(1, n + 1):
        candidates = []
        for d in range(1, n + 1):
            if d != c and dist[c][d] != float('inf'):
                candidates.append((dist[c][d], d))
        if not candidates:
            best_from[c] = []
        else:
            candidates.sort(reverse=True)
            best_from[c] = candidates[:2]

    max_dist = -1
    result = None

    for b in range(1, n + 1):
        for c in range(1, n + 1):
            if b == c or dist[b][c] == float('inf') or not best_to[b] or not best_from[c]:
                continue

            for a_val, a in best_to[b]:
                for d_val, d in best_from[c]:
                    if a_val == float('inf') or d_val == float('inf'):
                        continue
                    # a, b, c, d must be distinct
                    if a == b or a == c or a == d or d == b or d == c:
                        continue

                    total = a_val + dist[b][c] + d_val
                    if total > max_dist:
                        max_dist = total
                        result = (a, b, c, d)

    return ' '.join(map(str, result)) if result else ""


