Looking at this problem, I need to:
1. Count axis-aligned squares (sides parallel to matrix rows/columns)
2. Count diagonal squares (sides parallel to diagonals - diamond/rotated squares)
3. For both types: border must be all 1s, interior must contain at least one 1, and no foreign 1s can touch the border by side or corner

Let me write a solution that handles both square types:

```python
def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return ''

    lines = input_str.split('\n')
    t = int(lines[0])
    results = []

    idx = 1
    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for _ in range(n):
            matrix.append(list(lines[idx]))
            idx += 1

        count = 0

        # Type 1: Axis-aligned squares (sides parallel to matrix)
        for k in range(2, min(n, m) + 1):
            for r in range(n - k + 1):
                for c in range(m - k + 1):
                    # Check if border is all 1s
                    top_ok = all(matrix[r][c + j] == '1' for j in range(k))
                    bottom_ok = all(matrix[r + k - 1][c + j] == '1' for j in range(k))
                    left_ok = all(matrix[r + i][c] == '1' for i in range(k))
                    right_ok = all(matrix[r + i][c + k - 1] == '1' for i in range(k))

                    if not (top_ok and bottom_ok and left_ok and right_ok):
                        continue

                    # Check for foreign 1s (touching border by side or corner)
                    # For each border cell, check its 8 neighbors
                    foreign_ok = True
                    for i in range(k):
                        for j in range(k):
                            # Skip interior - only check border cells and their neighbors
                            if 0 < i < k - 1 and 0 < j < k - 1:
                                continue

                            # Check all 8 neighbors
                            for di in [-1, 0, 1]:
                                for dj in [-1, 0, 1]:
                                    if di == 0 and dj == 0:
                                        continue
                                    ni, nj = r + i + di, c + j + dj
                                    if 0 <= ni < n and 0 <= nj < m:
                                        if matrix[ni][nj] == '1':
                                            foreign_ok = False
                                            break
                                if not foreign_ok:
                                    break
                            if not foreign_ok:
                                break

                        if not foreign_ok:
                            break

                    if foreign_ok:
                        count += 1

        # Type 2: Diagonal squares (diamond shape)
        for k in range(2, min(n, m) + 1):
            radius = k - 1

            # Diamond centered at (cr, cc) with top point k cells above, bottom k-1 below
            for r in range(n - 2 * radius):
                for c in range(m - 2 * radius):
                    center_r = r + radius
                    center_c = c + radius
                    top = (r, center_c)
                    bottom = (r + 2 * radius, center_c)
                    left = (center_r, c)
                    right = (center_r, c + 2 * radius)

                    # Check all 4 corners are 1
                    if (matrix[top[0]][top[1]] != '1' or
                        matrix[bottom[0]][bottom[1]] != '1' or
                        matrix[left[0]][left[1]] != '1' or
                        matrix[right[0]][right[1]] != '1'):
                        continue

                    # Check entire border is 1s
                    # Top edge: row r, columns c to 2*radius + c
                    top_ok = all(matrix[r][c + j] == '1' for j in range(1, radius + 1))
                    if not top_ok:
                        continue

                    # Bottom edge: row 2*radius + r, columns c to 2*radius + c
                    bottom_ok = all(matrix[r + 2 * radius][c + j] == '1' for j in range(1, radius + 1))
                    if not bottom_ok:
                        continue

                    # Left edge: column c, rows r+1 to 2*radius-1 + r
                    left_ok = all(matrix[r + i][c] == '1' for i in range(1, radius + 1))
                    if not left_ok:
                        continue

                    # Right edge: column 2*radius + c, rows r+1 to 2*radius-1 + r
                    right_ok = all(matrix[r + i][c + 2 * radius] == '1' for i in range(1, radius + 1))
                    if not right_ok:
                        continue

                    # Check for foreign 1s around border
                    foreign_ok = True
                    # Check corners' neighbors
                    for pt in [top, bottom, left, right]:
                        for di in [-1, 0, 1]:
                            for dj in [-1, 0, 1]:
                                if di == 0 and dj == 0:
                                    continue
                                ni, nj = pt[0] + di, pt[1] + dj
                                if 0 <= ni < n and 0 <= nj < m and matrix[ni][nj] == '1':
                                    foreign_ok = False
                                    break
                            if not foreign_ok:
                                break
                        if not foreign_ok:
                            break

                    if foreign_ok:
                        count += 1

        results.append(str(count))

    return '\n'.join(results)


