    # We can simply use all 'A's
    if x == 0:
        s1 = 'A' * n
        s2 = 'A' * m
        ck = generate_sk(s1, s2, k)
        if count_ac(ck) == 0:
            return s1 + '\n' + s2
        return "Happy new year!\n"

    # Try to construct strings with specific AC patterns
    # The key insight is that we can control AC occurrences by strategic placement of 'A' and 'C'

    # Base patterns to try:
    # - Only 'A's (no AC)
    # - Only 'C's (no AC)
    # - Mix 'A' and 'C' at specific positions

    possible_patterns = generate_patterns(n, m)

    for s1, s2 in possible_patterns:
        ck = generate_sk(s1, s2, k)
        if count_ac(ck) == x:
            return s1 + '\n' + s2

    return "Happy new year!\n"

def generate_sk(s1, s2, k):
    """Generate sk using the recurrence relation sn = sn-2 + sn-1"""
    if k == 1:
        return s1
    elif k == 2:
        return s2
    else:
        s = [s1, s2]
        for i in range(3, k + 1):
            prev2 = s[i-3]
            prev1 = s[i-2]
            s.append(prev2 + prev1)
        return s[-1]

def generate_patterns(n, m):
    """Generate various patterns for s1 and s2"""
    patterns = []

    # Pattern 1: All 'A's
    patterns.append(('A' * n, 'A' * m))

    # Pattern 2: All 'C's
    patterns.append(('C' * n, 'C' * m))

    # Pattern 3: Single 'C' at different positions
    for i in range(n):
        patterns.append(('A' * i + 'C' + 'A' * (n - 1 - i), 'A' * m))
    for i in range(m):
        patterns.append(('A' * n, 'A' * i + 'C' + 'A' * (m - 1 - i)))

    # Pattern 4: AC pattern
    patterns.append(('AC' * (n // 2) + ('A' if n % 2 else ''), 'AC' * (m // 2) + ('A' if m % 2 else '')))

    # Pattern 5: Try to exactly create x ACs
    # We can use a pattern that has 1 AC at each concatenation point
    if n >= 2 and m >= 1:
        patterns.append(('A' * (n-1) + 'C', 'A' * m))
    if n >= 1 and m >= 2:
        patterns.append(('A' * n, 'A' * (m-1) + 'C'))

    # Pattern 6: Try minimal string with AC
    if n <= 5:  # Small n for complexity
        for c1 in ['A', 'C', 'B', 'D', 'E']:
            for c2 in range(max(0, 5 - n) if n > len('ABC') else 5 - n):
                pass
            patterns.append(('A' * (n-1) + 'C', 'A' * m))
        patterns.append(('A' * n, 'A' * (m-1) + 'C'))

    # Pattern 7: For large x, try patterns with many ACs
    patterns.append(('C' * n + 'A', 'A' * m))
    patterns.append(('A' * n, 'C' + 'B' * m))
    patterns.append(('A' * n, 'A' * (m-2) + 'AC'))

    return patterns

