import math
from collections import defaultdict, deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    adj = defaultdict(list)
    for i in range(2, len(lines)):
        u, v = map(int, lines[i].split())
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)

    def get_dist(u, v):
        dist = [-1] * n
        dist[u] = 0
        queue = deque([u])
        while queue:
            curr = queue.popleft()
            if curr == v:
                return dist[curr]
            for neighbor in adj[curr]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[curr] + 1
                    queue.append(neighbor)
        return dist

    def calc_weight(root):
        deg = [len(adj[u]) for u in range(n)]
        total = sum(deg[u] * a[u] for u in range(n))

        for u, v in adj[root]:
            total += int(math.log2(max(1, u - v + 1))) * min(a[u], a[v])

        return total

    ans = float('inf')
    for i in range(n):
        if a[i] >= min(a):
            ans = calc_weight(i)
            break
    return str(ans)
