def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    MOD = 10**9 + 7

    current = a.copy()
    start_add = True  # First row always starts with addition

    while len(current) > 1:
        new_row = []
        for i in range(len(current) - 1):
            # Position 0, 2, 4... use the starting operation
            # Position 1, 3, 5... use the opposite operation
            if i % 2 == 0:
                if start_add:
                    val = (current[i] + current[i+1]) % MOD
                else:
                    val = (current[i] - current[i+1]) % MOD
            else:
                if start_add:
                    val = (current[i] - current[i+1]) % MOD
                else:
                    val = (current[i] + current[i+1]) % MOD
            new_row.append(val)

        current = new_row
        # Flip starting operation for next row
        start_add = not start_add

    result = current[0] % MOD
    return str(result)
