        return '1' if c == '0' else '0'

    def reverse_str(s):
        return s[::-1]

    def get_canonical(s):
        """Get minimum string in equivalence class"""
        variants = [
            s,
            reverse_str(s),
            ''.join(swap_char(c) for c in s),
            ''.join(swap_char(c) for c in reverse_str(s))
        ]
        return min(variants)

    # Generate canonical strings and sort
    canonical_set = set()
    seen = set()

    for i in range(1 << n):
        s = bin(i)[2:].zfill(n)
        canonical = get_canonical(s)
        if canonical not in seen:
            seen.add(canonical)
            canonical_set.add(canonical)

    sorted_canonical = sorted(canonical_set)

    if k <= len(sorted_canonical):
        return sorted_canonical[k - 1]
    else:
        return "-1"
